const cds = require('../../../cds')
const { exists, read } = cds.utils
const { readProject } = require('../../projectReader')
const { merge } = require('../../merge')
const { srv4, xsuaa, mtxSidecar4 } = require('../../registries/mta')
const KymaTemplate = require('../kyma')

module.exports = class XsuaaTemplate extends require('../../plugin') {

    options() {
        return {
            'plan': {
                type: 'string',
                help: 'Specify the service plan.',
            }
        }
    }

    static help() {
        return 'authentication via XSUAA'
    }

    static hasInProduction(env) {
        return env.requires?.auth?.kind === 'xsuaa' || cds.cli.options?.add?.has('xsuaa') || false
    }

    async run() {
        const project = readProject()
        const { configFile } = project
        project.shortcut = !exists(configFile) || typeof (await read(configFile)).cds?.requires?.auth !== 'object'
        project.profile ??= 'production'
        await merge(__dirname, 'files/package.json.hbs').into(configFile, { project, forceOverwrite: true })
    }

    async combine(facet) {
        const project = readProject(facet)
        const { affected, isJava, srv } = project

        let xsSecurity
        if (affected('xsuaa', 'sample', 'multitenancy', 'extensibility')) {
            const cds = require('../../../../lib')
            xsSecurity = await (async () => {
                try {
                    const models = await cds.load(cds.env.folders.srv)
                    return cds.compile.to.xsuaa(models)
                } catch { /* ignore */ }
            })() ?? { scopes: [], attributes: [], 'role-templates': [], 'authorities-inheritance': false }

            const additions = xsSecurity.scopes.map(scope => ({ in: 'scopes', where: { name: scope.name } }))
            await merge(xsSecurity).into('xs-security.json', { project, additions })
        }

        if (affected('mta', 'multitenancy', 'extensibility')) {
            xsSecurity ??= exists('xs-security.json') ? await read('xs-security.json') : {}
            const roles = xsSecurity['role-templates'] ?? []
            const additions = [], overwrites = [], relationships = []
            const { plan } = cds.cli.options
            additions.push(xsuaa)
            if (plan) overwrites.push({ item: [xsuaa, 'parameters.service-plan'], withValue: plan })
            if (affected('mta')) {
                const srvModule = srv4(srv.path)
                relationships.push({
                    insert: [xsuaa, 'name'],
                    into: [srvModule, 'requires', 'name']
                })
            }
            if (affected('multitenancy', 'mta')) {
                const mtxSidecar = mtxSidecar4(isJava ? 'mtx/sidecar' : 'gen/mtx/sidecar')
                overwrites.push({ item: [xsuaa, 'parameters.config.tenant-mode'], withValue: 'shared' })
                relationships.push({
                    insert: [xsuaa, 'name'],
                    into: [mtxSidecar, 'requires', 'name']
                })
            }
            if (plan) project.servicePlan = plan

            project.hasRoles = roles.length > 0
            project.roles = roles

            if (!project.hasCustomRoleCollections) {
                for (const role of roles) {
                    additions.push({
                        in: [xsuaa, 'parameters.role-collections'],
                        where: { 'role-template-references': ['XSAPPNAME'+role.name] }
                    })
                }
            }
            await merge(__dirname, 'files/mta.yaml.hbs').into('mta.yaml', { project, additions, overwrites, relationships })
            if (project.hasExtensibility) {
                const extTemplate = require('path').join(__dirname, '../extensibility')
                await merge(extTemplate, 'files', 'mta.yaml.hbs').into('mta.yaml', {
                    project,
                    additions: [
                        xsuaa,
                        { in: [xsuaa, 'parameters.config.role-collections'], where: { name: `ExtensionDeveloper (${project.appName} \${org}-\${space})` } }
                    ]
                })
            }
        }

        if (affected('kyma', 'multitenancy', 'extensibility')) {
            xsSecurity ??= exists('xs-security.json') ? await read('xs-security.json') : {}
            const roles = xsSecurity['role-templates'] ?? []
            const overwrites = affected('multitenancy') ? [{ item: 'xsuaa.parameters.tenant-mode', withValue: 'shared' }] : []
            const { plan } = cds.cli.options
            if (plan) {
                project.servicePlan = plan
                overwrites.push({ item: 'xsuaa.servicePlanName', withValue: plan })
            }
            await merge(__dirname, 'files/values.yaml.hbs').into('chart/values.yaml', { with: project, overwrites })
            const parameters = {
                xsappname: `${project.appName}-{{ .Release.Namespace }}`
            }
            if (!project.hasCustomRoleCollections && roles.length) {
                parameters['role-collections'] = roles.map(role => ({
                    name: `${role.name} (${project.appName} {{ .Release.Namespace }})`,
                    description: 'generated',
                    'role-template-references': [`$XSAPPNAME.${role.name}`],
                }))
            }
            if (project.hasExtensibility) {
                parameters['role-collections'] ??= []
                parameters['role-collections'].push({
                    name: `ExtensionDeveloper (${project.appName} {{ .Release.Namespace }})`,
                    description: 'generated',
                    'role-template-references': ['$XSAPPNAME.ExtensionDeveloper'],
                })
            }
            await merge({ xsuaa: { parameters } }).into('chart/values.yaml')
            await KymaTemplate.mergeDependency('service-instance', 'xsuaa')

        }
    }
}
